import sys


def main(argv):
    try:
        celsius = float(argv[1])
    except (IndexError, ValueError):
        print("error: expected a number", file=sys.stderr)
        return 2
    print(f"{celsius * 9 / 5 + 32:.1f}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
